from decimal import Decimal, ROUND_HALF_UP

def money(x):
    """Round to cents with ROUND_HALF_UP on the decimal string form,
    so results match financial half-up rounding for negatives too."""
    return float(Decimal(str(x)).quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))

Decimal(str(x)) avoids the binary-float representation error that makes round(x, 2) return 2.67 for 2.675.
